-- =====================================================================
-- Migration 076: Cloudflare WARP AWG2 client egress via netns
-- Routes AmneziaWG2 client TCP+UDP egress through an isolated
-- WARP WireGuard network namespace. Host default route, SSH,
-- panel access and client configs remain unchanged.
-- =====================================================================

UPDATE protocols
SET
  name = 'Cloudflare WARP Egress',
  description = 'Cloudflare WARP client egress for AmneziaWG 2.0. Routes AWG2 client TCP and UDP egress through an isolated WARP WireGuard network namespace while keeping SSH, panel, host default route and client configs unchanged.',
  install_script = FROM_BASE64(''),
  uninstall_script = FROM_BASE64(''),
  output_template = FROM_BASE64(''),
  show_text_content = 1,
  is_active = 1,
  definition = JSON_OBJECT(
    'engine', 'shell',
    'metadata', JSON_OBJECT(
      'container_name', 'amnezia-awg2',
      'target_protocol', 'awg2',
      'config_dir', '/opt/amnezia/awg2',
      'config_file', 'awg0.conf',
      'routes_client_egress', true,
      'routing_method', 'warp_wireguard_netns_policy_routing',
      'client_configs_unchanged', true,
      'routing_scope', 'tcp_udp_client_egress',
      'route_table', 51888,
      'mark', '0x2cf2'
    )
  ),
  updated_at = NOW()
WHERE slug = 'cf-warp';
